        .favor-bar::after { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: linear-gradient(to right, rgba(255,255,255,0) 0%, rgba(255,255,255,0.5) 50%, rgba(255,255,255,0) 100%); animation: shimmer 2s infinite; }
        .progress-text { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); font-size: 0.8em; font-weight: bold; color: var(--font-color-white); text-shadow: 0 0 3px rgba(0, 0, 0, 0.8); pointer-events: none; z-index: 2; }
        .relationship-actions { margin-top: 10px; display: flex; justify-content: flex-end; }
        .sever-relationship-btn {
            padding: 6px 12px; font-size: 0.8em; font-weight: bold; color: rgba(255, 228, 225, 0.85); background: linear-gradient(145deg, #6a2a28, #4e1e1c);
            border: 1px solid #412323; border-radius: 6px; cursor: pointer; position: relative; overflow: hidden;
            text-shadow: 0 0 4px rgba(255, 100, 100, 0.5); box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.1), 0 1px 3px rgba(0,0,0,0.4);
            transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
        }
        .sever-relationship-btn:hover { color: #fff; border-color: #c9302c; box-shadow: inset 0 1px 2px rgba(0,0,0,0.2), 0 2px 8px rgba(0,0,0,0.5), 0 0 15px rgba(255, 80, 80, 0.6); transform: translateY(-1px); text-shadow: 0 0 6px rgba(255, 150, 150, 0.8); }
        .sever-relationship-btn:active { transform: translateY(0px); box-shadow: inset 0 1px 2px rgba(0,0,0,0.5); transition: all 0.1s ease; }

        .map-container .map-layout { display: flex; width: 100%; height: 100%; gap: 15px; }
        .map-location-list {
            flex: 4; display: flex; flex-direction: column; gap: 10px; padding: 10px; border-radius: 8px;
            background: linear-gradient(135deg, rgba(107, 79, 58, 0.1), rgba(169, 146, 126, 0.15));
            box-shadow: inset 0 0 15px rgba(91, 67, 41, 0.2);
        }
        .map-location-btn {
            display: flex; align-items: center; text-align: left; padding: 12px 15px; background: rgba(253, 250, 245, 0.3);
            border: 1px solid rgba(169, 146, 126, 0.4); border-radius: 6px; cursor: pointer; transition: all 0.3s ease;
            font-weight: bold; color: var(--font-color-medium); position: relative; overflow: hidden;
        }
        .map-location-btn::before, .map-location-btn::after { font-family: var(--font-family-symbol); color: var(--font-color-light); transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), color 0.3s, text-shadow 0.3s; flex-shrink: 0; }
        .map-location-btn::before { content: '⛫'; font-size: 1.4em; margin-right: 12px; }
        .map-location-btn span { flex-grow: 1; }
        .map-location-btn::after { content: '☰'; font-size: 1.4em; margin-left: 12px; }
        .map-location-btn.selected::after { transform: rotate(90deg); }
        .map-location-btn:hover, .map-location-btn.selected {
            background-color: rgba(212, 175, 55, 0.2); border-color: var(--color-primary-gold-shadow); color: var(--font-color-title);
            box-shadow: 0 2px 8px rgba(0,0,0,0.1), inset 0 0 10px rgba(212, 175, 55, 0.15);
        }
        .map-location-btn:hover::before, .map-location-btn:hover::after, .map-location-btn.selected::before, .map-location-btn.selected::after { color: var(--color-primary-gold); text-shadow: 0 0 5px var(--color-primary-gold-glow); }
        .map-location-details {
            flex: 6; padding: 25px; border-radius: 8px; background: linear-gradient(to bottom, rgba(250, 245, 235, 0.7), rgba(240, 233, 220, 0.85));
            box-shadow: 0 4px 12px rgba(91, 67, 41, 0.1), inset 0 2px 10px rgba(255,255,255,0.5);
            display: flex; flex-direction: column; align-items: center; justify-content: center;
        }
        .map-details-title { font-size: 1.6em; color: var(--font-color-title); margin-bottom: 20px; text-shadow: 1px 1px 2px #fff; }
        .map-details-desc { font-size: 1em; line-height: 1.7; color: var(--font-color-dark); text-align: left; margin-bottom: 25px; width: 100%; }
        .map-details-go-btn { margin-top: auto; }

        .attribute-panel { display: grid; grid-template-columns: 1fr; gap: 15px; width: 100%; }
        .attribute-category { background: rgba(248, 243, 233, 0.5); border: 1px solid var(--border-color-light); border-radius: 10px; padding: 15px 20px; box-shadow: 0 2px 5px rgba(91, 67, 41, 0.08); }
        .attribute-category h3 { font-size: 1.2em; color: var(--font-color-title); margin: 0 0 12px 0; padding-bottom: 8px; border-bottom: 2px solid var(--border-color-light); text-shadow: 1px 1px 2px rgba(255,255,255,0.3); text-align: left; }
        .attribute-list { list-style: none; padding: 0; margin: 0; }
        .attribute-item { display: flex; justify-content: space-between; padding: 8px 0; font-size: 0.95em; border-bottom: 1px dashed var(--border-color-light); }
        .attribute-item:last-child { border-bottom: none; }
        .attribute-name { color: var(--font-color-medium); font-weight: bold; }
        .attribute-value { color: var(--font-color-dark); font-weight: bold; text-align: right; }

        /* 通用滚动条样式 */
        .text-scroll::-webkit-scrollbar, .memory-list::-webkit-scrollbar, .task-log-container::-webkit-scrollbar, .relationship-container::-webkit-scrollbar, .attribute-panel-container::-webkit-scrollbar { width: 8px; }
        .text-scroll::-webkit-scrollbar-track, .memory-list::-webkit-scrollbar-track, .task-log-container::-webkit-scrollbar-track, .relationship-container::-webkit-scrollbar-track, .attribute-panel-container::-webkit-scrollbar-track { background: rgba(223, 212, 196, 0.5); border-radius: 4px; }
        .text-scroll::-webkit-scrollbar-thumb, .memory-list::-webkit-scrollbar-thumb, .task-log-container::-webkit-scrollbar-thumb, .relationship-container::-webkit-scrollbar-thumb, .attribute-panel-container::-webkit-scrollbar-thumb { background: var(--border-color-medium); border-radius: 4px; border: 1px solid rgba(91, 67, 41, 0.2); }
        .text-scroll::-webkit-scrollbar-thumb:hover, .memory-list::-webkit-scrollbar-thumb:hover, .task-log-container::-webkit-scrollbar-thumb:hover, .relationship-container::-webkit-scrollbar-thumb:hover, .attribute-panel-container::-webkit-scrollbar-thumb:hover { background: var(--font-color-medium); }

        /* 用户输入区域样式 */
        .message-input-area { display: flex; align-items: stretch; gap: 10px; padding: 8px; background-color: rgba(240, 233, 220, 0.85); border: 1px solid var(--border-color-medium); border-radius: 10px; flex-shrink: 0; transition: box-shadow 0.3s ease; position: relative; overflow: hidden; }
        .message-input-area:focus-within { animation: focus-glow 2s ease-in-out infinite; }
        .message-input-area textarea { flex-grow: 1; height: 40px; resize: none; border: 1px solid #C5B8A9; border-radius: 6px; padding: 8px 12px; font-family: inherit; font-size: 0.95em; color: var(--font-color-dark); background-color: #FDFBFA; box-shadow: inset 0 1px 3px rgba(0,0,0,0.05); transition: border-color 0.3s ease; box-sizing: border-box; }
        .message-input-area textarea:focus { outline: none; border-color: var(--border-color-medium); }
        .message-input-area button { flex-shrink: 0; padding: 0 18px; border-radius: 6px; border: 1px solid var(--border-color-medium); background: linear-gradient(to bottom, #9b7e6d, #8D6E63); color: var(--font-color-white); font-weight: bold; cursor: pointer; transition: all 0.2s ease; text-shadow: 0 -1px 0 rgba(0,0,0,0.2); position: relative; overflow: hidden; }
        .message-input-area button:active { background: linear-gradient(to top, #9b7e6d, #8D6E63); transform: translateY(1px); }
        .ripple { position: absolute; border-radius: 50%; background-color: var(--color-primary-gold-shadow); transform: scale(0); animation: ripple-effect 1s linear; pointer-events: none; }

        /* 响应式设计：针对小屏幕设备的样式覆盖 */
        @media (max-width: 768px) {
            .calendar-bar { line-height: 1.5; padding: 5px 10px; }
            .fused-scroll-content { flex-direction: column; align-items: stretch; }
            .left-panel { align-self: initial; min-height: auto; }
            .left-panel, .right-panel { width: 100%; flex: auto; }
            .embedded-avatar { width: 80px; height: 112px; }
            .text-scroll-area { min-height: 500px; margin-bottom: 10px; }
            .right-panel { gap: 10px; }
            .fused-scroll-header, .calendar-bar, .text-scroll-area { margin: 0; }
            .guide-container, .menu-options-container, .deduction-options-container, .memory-container, .task-log-container, .relationship-container, .map-container, .attribute-panel-container { max-width: 90%; margin: auto; }
            .guide-container .notes { padding: 0 5px; }
            .save-slot-entry { flex-direction: row; gap: 8px; max-width: 90%;}
            .deduction-options-container .options-grid, .inventory-container .options-grid { grid-template-columns: 1fr; }
            .map-container .map-layout { flex-direction: column; }
        }
    </style>
</head>
<body>
    <!-- 主容器 -->
    <div class="fused-scroll-container">
        <!-- 背景动态粒子效果 -->
        <div class="spiritual-energy-flow"></div>

        <!-- 主要内容区 -->
        <div class="fused-scroll-content">
            <!-- 左侧面板 -->
            <div class="left-panel">
                <!-- 角色头像与信息区 -->
                <div class="avatar-section">
                    <div class="embedded-avatar"><div class="user_avatar"></div></div>
                    <div class="avatar-info-panel">
                        <div class="info-item"><strong class="info-name">{{user}}</strong></div>
                        <div class="info-item"><strong>性别:</strong> <span id="charSex">未知</span></div>
                        <div class="info-item"><strong>年龄:</strong> <span id="charAge">未知</span></div>
                        <div class="info-item"><strong>境界:</strong> <span id="charRealm">未知</span></div>
                    </div>
                </div>
                <!-- 功能导航按钮区 -->
                <div class="function-nav-area">
                    <div class="function-nav-button" data-menu="灵境感知" data-trigram="☰"><span>灵境感知</span></div>
                    <div class="function-nav-button" data-menu="周天舆图" data-trigram="☷"><span>周天舆图</span></div>
                    <div class="function-nav-button" data-menu="尘缘绘卷" data-trigram="☲"><span>尘缘绘卷</span></div>
                    <div class="function-nav-button" data-menu="诸天宝录" data-trigram="☳"><span>诸天宝录</span></div>
                    <div class="function-nav-button" data-menu="袖里乾坤" data-trigram="☶"><span>袖里乾坤</span></div>
                    <div class="function-nav-button" data-menu="前尘忆梦" data-trigram="☵"><span>前尘忆梦</span></div>
                    <div class="function-nav-button" data-menu="天机推演" data-trigram="☴"><span>天机推演</span></div>
                    <div class="function-nav-button" data-menu="轮回之刻" data-trigram="☱"><span>轮回之刻</span></div>
                </div>
            </div>
            <!-- 右侧面板 -->
            <div class="right-panel">
                <!-- 顶部标题 -->
                <div class="fused-scroll-header"><div class="header-title-text">太虚幻境</div></div>
                <!-- 日历与地点信息 -->
                <div class="calendar-bar"><div><span class="time-info">未知</span><br><span class="location-info">未知</span></div></div>
                <!-- 主要文本显示区 -->
                <div class="text-scroll-area">
                    <div class="lined-paper-overlay"></div>
                    <div class="text-scroll"></div>
                </div>
                <!-- 用户输入区 -->
                <div class="message-input-area">
                    <textarea id="userInput" placeholder="传音入密，衍化天机..."></textarea>
                    <button id="sendButton">传音</button>
                </div>
            </div>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', async () => {
            // ---- 模块1: DOM元素获取与缓存 ----
            // 缓存所有需要频繁操作的DOM元素，提高性能
            const sendButton = document.getElementById('sendButton');
            const userInput = document.getElementById('userInput');
            const textScroll = document.querySelector('.text-scroll');
            const timeInfoElem = document.querySelector('.time-info');
            const locationInfoElem = document.querySelector('.location-info');
            const charSexElem = document.getElementById('charSex');
            const charAgeElem = document.getElementById('charAge');
            const charRealmElem = document.getElementById('charRealm');
            const functionNavArea = document.querySelector('.function-nav-area');

            // ---- 模块2: 全局状态与核心数据 ----
            // 默认的世界状态，作为新游戏或加载失败时的基础
            const defaultWorldState = {
                sex: "未知", age: "未知", realm: "未知", time: "未知", location: "未知",
                inventory: [], tasks: [], relationships: [], discoveredLocations: [],
                characterAttributes: {
                    minge: "待定", linggen: "待定", tizhi_special: "待定",
                    tianfu: "待定", gongfa: "无", shentong: "无",
                    zhuangbei: "无", wuqi: "无", fabao: "无", daoxin: 0, qiyun: 0, shenshi: 0,
                    fali: 0, tizhi_attr: 0, meili: 0
                }
            };
            const MAX_SAVE_SLOTS = 8;
            // 核心状态变量
            let currentMode = 'GUIDE_MODE'; // 控制当前UI显示模式
            let worldState = { ...defaultWorldState }; // 存储所有游戏世界的数据
            let chatDisplayContent = ""; // 缓存聊天内容的HTML字符串，用于完整重绘
            let deductionOptions = []; // AI提供的推演选项
            let smallSummaries = []; // 中期记忆摘要列表
            let interactionCounter = 0; // 交互计数器（暂未完全利用）
            let isSummarizing = false; // 大总结任务进行中的标志位，防止重复触发
            let activeMenuButton = null; // 当前激活的导航按钮
            let modeBeforeMenu = null; // 进入菜单前的UI模式，用于返回
            let currentCharacterName = 'default_char'; // 当前聊天标识符，用于存档
            let lastUserMessage = ""; // 缓存上一次用户输入，用于重试
            let isAwaitingFirstAction = false; // 是否等待开局后的第一次行动
            let lastInteractionSnapshot = {}; // 用于“天机重演”功能的交互快照
            let lastSavedWorldState = null; // 用于增量保存的状态快照

            // ---- 模块3: 核心辅助函数 ----
            // Base64编码/解码，用于在SillyTavern变量中安全存储复杂数据
            const encodeText = (text) => btoa(unescape(encodeURIComponent(text)));
            const decodeText = (b64) => decodeURIComponent(escape(atob(b64)));
            // 安全的JSON解析函数，增加对常见错误的修复能力
            const safeJSONParse = (jsonString, defaultValue) => {
                if (!jsonString || typeof jsonString !== 'string' || jsonString.trim() === '' || jsonString === 'undefined' || jsonString === 'null') return defaultValue;
                try {
                    // 尝试修复JSON中常见的末尾逗号错误
                    const fixedJsonString = jsonString.replace(/,\s*([}\]])/g, '$1');
                    return JSON.parse(fixedJsonString);
                } catch (e) {
                    console.error("JSON 解析失败:", e, "原始字符串:", jsonString);
                    return defaultValue;
                }
            };
            // 从SillyTavern获取当前聊天文件名作为角色标识
            const getCurrentCharacterNameFromTavern = async () => {
                if (typeof triggerSlashWithResult !== 'function') return 'default_character';
                try {
                    const name = await triggerSlashWithResult('/getchatname');
                    return (name && name.trim() !== '' && name !== 'undefined') ? name.replace('.jsonl', '') : 'default_character';
                } catch (e) { return 'default_character'; }
            };
            // 深层比较两个对象是否相等，用于增量保存的判断
            const deepEqual = (obj1, obj2) => {
                if (obj1 === obj2) return true;
                if (typeof obj1 !== 'object' || obj1 === null || typeof obj2 !== 'object' || obj2 === null) return false;
                const keys1 = Object.keys(obj1);
                const keys2 = Object.keys(obj2);
                if (keys1.length !== keys2.length) return false;
                for (let key of keys1) {
                    if (!keys2.includes(key) || !deepEqual(obj1[key], obj2[key])) return false;
                }
                return true;
            };

            // ---- 模块4: 状态持久化（存档/读档）----
            // 将游戏状态保存到SillyTavern全局变量中（已实现增量检查）
            const saveStateToSillyTavern = async () => {
                if (typeof triggerSlash !== 'function' || !currentCharacterName) return;
                // 只有在世界状态发生真实变化时才执行保存，避免不必要的性能开销
                if (lastSavedWorldState && deepEqual(worldState, lastSavedWorldState)) {
                    return;
                }
                const characterState = {
                    currentUIMode: currentMode, worldGlobalState: worldState, chatDisplayContent: chatDisplayContent,
                    deductionOptions: deductionOptions, smallSummaries: smallSummaries, interactionCounter: interactionCounter,
                    lastUserMessage: lastUserMessage, isAwaitingFirstAction: isAwaitingFirstAction, TavernSaveSlots: await getSaveSlots()
                };
                const stateJson = JSON.stringify(characterState);
                await triggerSlash(`/setglobalvar key=persistentUIStates index="${currentCharacterName}" ${stateJson}`);
                // 更新上一次成功保存的状态快照
                lastSavedWorldState = JSON.parse(JSON.stringify(worldState));
            };
            // 从SillyTavern全局变量中加载游戏状态
            const loadStateFromSillyTavern = async () => {
                if (typeof triggerSlashWithResult !== 'function') return false;
                currentCharacterName = await getCurrentCharacterNameFromTavern();
                // 优先处理通过URL参数传递的临时读档数据
                const loadMode = await triggerSlashWithResult('/getvar key=st_ui_load_mode');
                if (loadMode && loadMode.trim() !== '') {
                    try {
                        const b64_worldState = await triggerSlashWithResult('/getvar key=st_ui_load_world');
                        const b64_chatContent = await triggerSlashWithResult('/getvar key=st_ui_load_chat');
                        const b64_deductionOptions = await triggerSlashWithResult('/getvar key=st_ui_load_options');
                        const b64_smallSummaries = await triggerSlashWithResult('/getvar key=st_ui_load_summaries');
                        const savedCounter = await triggerSlashWithResult('/getvar key=st_ui_load_counter');
                        const savedLastMessage = await triggerSlashWithResult('/getvar key=st_ui_load_last_message');
                        currentMode = loadMode;
                        worldState = JSON.parse(decodeText(b64_worldState));
                        chatDisplayContent = decodeText(b64_chatContent);
                        deductionOptions = JSON.parse(decodeText(b64_deductionOptions || '[]'));
                        smallSummaries = JSON.parse(decodeText(b64_smallSummaries || '[]'));
                        interactionCounter = parseInt(savedCounter || '0', 10);
                        lastUserMessage = decodeText(savedLastMessage || '');
                        isAwaitingFirstAction = true;
                        // 清除临时读档变量
                        await triggerSlash('/flushvar st_ui_load_mode || /flushvar st_ui_load_world || /flushvar st_ui_load_chat || /flushvar st_ui_load_options || /flushvar st_ui_load_summaries || /flushvar st_ui_load_counter || /flushvar st_ui_load_last_message');
                        await saveStateToSillyTavern();
                        return true;
                    } catch (error) { console.error("从临时读档变量加载失败:", error); }
                }
                // 正常加载持久化存档
                const savedStateJson = await triggerSlashWithResult(`/getglobalvar index="${currentCharacterName}" persistentUIStates`);
                const savedState = safeJSONParse(savedStateJson, null);
                if (savedState) {
                    currentMode = savedState.currentUIMode || 'GUIDE_MODE';
                    worldState = savedState.worldGlobalState || { ...defaultWorldState };
                    // 兼容旧存档，确保新数据结构存在
                    if (!worldState.tasks) worldState.tasks = [];
                    if (!worldState.relationships) worldState.relationships = [];
                    if (!worldState.discoveredLocations) worldState.discoveredLocations = [];
                    if (!worldState.characterAttributes) worldState.characterAttributes = { ...defaultWorldState.characterAttributes };
                    chatDisplayContent = savedState.chatDisplayContent || "";
                    deductionOptions = savedState.deductionOptions || [];
                    smallSummaries = savedState.smallSummaries || [];
                    interactionCounter = savedState.interactionCounter || 0;
                    lastUserMessage = savedState.lastUserMessage || "";
                    isAwaitingFirstAction = savedState.isAwaitingFirstAction || false;
                } else {
                    // 初始化新游戏的状态
                    currentMode = 'GUIDE_MODE';
                    worldState = { ...defaultWorldState };
                    chatDisplayContent = ""; deductionOptions = []; smallSummaries = [];
                    interactionCounter = 0; lastUserMessage = ""; isAwaitingFirstAction = false;
                }
                // 初始化状态快照，用于增量保存
                lastSavedWorldState = JSON.parse(JSON.stringify(worldState));
                return true;
            };

            // ---- 模块5: UI更新与渲染 ----
            // 更新顶部信息栏
            const updateCalendarBar = () => { timeInfoElem.innerHTML = `<span class="symbol">❂</span> ${worldState.time} <span class="symbol">❂</span>`; locationInfoElem.innerHTML = `『 ${worldState.location} 』`; };
            const updateAvatarPanel = () => { charSexElem.textContent = worldState.sex; charAgeElem.textContent = worldState.age; charRealmElem.textContent = worldState.realm; };
            // (性能优化) 追加新消息到聊天区，而不是重绘整个区域
            const appendMessage = (htmlString) => {
                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = htmlString.trim();
                const messageNode = tempDiv.firstChild;
                if (messageNode) {
                    textScroll.appendChild(messageNode);
                    // 自动滚动到底部
                    textScroll.scrollTop = textScroll.scrollHeight;
                }
            };
            // 完整渲染UI，主要用于模式切换或初始加载
            const renderContent = (isFullRender = true) => {
                if (isFullRender) {
                    const isIntroMode = currentMode === 'GUIDE_MODE' || currentMode === 'CREATION_MODE';
                    textScroll.classList.toggle('mode-centered', isIntroMode);
                    textScroll.innerHTML = ''; // 只有完全重绘时才清空

                    if (isIntroMode) {
                        const contentHTML = (currentMode === 'GUIDE_MODE') ? `
                            <div class="guide-container animate-fade-in-up">
                                <h2>游玩须知</h2><div class="notes"><p>【作者: 苏子河畔】<br>【禁止二传，允许二创】<br>【必备前置：最新版酒馆助手】<br>【本卡前端自带大小总结请关闭记忆表格】<br>【使用前请关闭非本卡外的多余拓展与脚本】<br>【如果变量无法正确更新请清除浏览器缓存】<br>【禁止一切商业化用途，本卡只在社区免费无偿发布】</p></div>
                                <button class="guide-btn" data-target-mode="CREATION_MODE">开启道途</button>
                            </div>` : `
                            <div class="creation-container animate-fade-in-up">
                                <h2>天命初定</h2><p>请为您的化身择定根骨：</p>
                                <div class="creation-options">
