            const handleDeleteSlot = async (slotId) => {
                let saveSlots = await getSaveSlots();
                const timestamp = saveSlots[slotId] ? saveSlots[slotId].timestamp : "该";
                if(confirm(`确定要抹去【${timestamp}】这份尘缘刻印吗？此举无法复原。`)){
                    delete saveSlots[slotId];
                    const fullStateJson = await triggerSlashWithResult(`/getglobalvar index="${currentCharacterName}" persistentUIStates`);
                    let fullState = safeJSONParse(fullStateJson, {}); fullState.TavernSaveSlots = saveSlots;
                    await triggerSlash(`/setglobalvar key=persistentUIStates index="${currentCharacterName}" ${JSON.stringify(fullState)}`);
                    await triggerSlash('/echo title="操作成功" 一份尘篇已然抹去。');
                    showLoadMenu();
                }
            };

            // ---- 模块7: AI通信协议与状态更新 ----
            const updateInventory = (itemsToAdd, showNotification = true) => {
                if (!itemsToAdd || itemsToAdd.length === 0) return;
                let notification = '【袖里乾坤】已收纳：';
                itemsToAdd.forEach(itemData => {
                    const itemName = itemData.name;
                    const quantity = itemData.quantity || 1;
                    const description = itemData.description || '此物来历神秘，其效用尚需探查。';
                    const existingItem = worldState.inventory.find(i => i.name === itemName);
                    if (existingItem) {
                        existingItem.quantity = (existingItem.quantity || 1) + quantity;
                    } else {
                        worldState.inventory.push({ id: `item_${Date.now()}_${Math.random()}`, name: itemName, quantity: quantity, description: description });
                    }
                    notification += `${itemName} x${quantity} `;
                });
                if (showNotification) {
                    triggerSlash(`/echo title="获得物品" ${notification}`);
                }
            };
            // (功能修改) 增强的常规交互指令
            const buildPromptForAI = (userMessage, shouldRequestSummary = false) => {
                const stateData = { time: worldState.time, location: worldState.location, age: worldState.age, realm: worldState.realm, ...worldState.characterAttributes };
                const activeTasksString = worldState.tasks.filter(t => t.status === 'active').map(t => `- ${t.title} (${t.description})`).join('\n') || '无';
                const relationshipsString = worldState.relationships.map(r => `- ${r.name} (好感度: ${r.favorability})`).join('\n') || '无';
                const attributesString = Object.entries(stateData).map(([key, value]) => `${key}: ${value}`).join('\n');

                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = chatDisplayContent;
                const recentMessages = Array.from(tempDiv.querySelectorAll('.user-message, .ai-message')).slice(-6);
                const recentHistoryText = recentMessages.map(node => {
                    const text = node.textContent || '';
                    if (node.classList.contains('user-message')) {
                        return `你: ${text.replace('你: ', '')}`;
                    }
                    return `AI: ${text}`;
                }).join('\n');

                const midTermMemory = smallSummaries.length > 0 ? `[中期记忆摘要]\n${smallSummaries.join('\n')}\n` : '';

                let prompt = `[长期记忆参考]\n请参考世界书中已记录的“前尘忆梦”作为核心故事背景。\n\n[角色背景]\n${attributesString}\n\n${midTermMemory}[近期对话历史]\n${recentHistoryText}\n\n[当前人际关系]\n${relationshipsString}\n\n[当前进行中的任务]\n${activeTasksString}\n\n[用户最新输入]\n${userMessage}\n\n[输出指令]\n1. 仔细分析互动是否会改变世界状态与角色属性。如有改变，请在下方对应行更新，如无改变则保持原样。\n2. 分析互动是否让玩家获得了新物品。如有，请在newItems行更新，格式为：[物品名|描述]。多个物品用分号(;)隔开。\n3. 分析互动是否触发了【新任务】。如有，请在newTasks行提供，格式为：[类型(主线/支线)]任务名|任务描述|任务奖励。多个任务用分号(;)隔开。\n4. 分析互动是否推进了【现有任务】。如有，请在taskProgress行提供，格式为：任务名|新的进度值(0-100)。多个任务用分号(;)隔开。如果任务完成，进度值设为100。\n5. 分析互动是否影响了【人际关系】。如有，在relationshipUpdates行提供，格式为：人名|+或-好感度变化值。多个用分号(;)隔开。\n6. 分析互动是否出现了【新人物】。如有，在newRelationships行提供，格式为：[身份]姓名|修为|描述|关系类型|初始好感度(0-100)。\n7. 分析互动是否发现了【新地点】。如有，在newDiscoveredLocations行提供，格式为：地点名|地点描述。多个用分号(;)隔开。\n8. **重要**: 如果角色属性有变化 (如法力、神识、气运等), 请在 newCharacterAttributes 行以JSON格式输出, 例如: {"fali": "10", "qiyun": "21"}\n9. 在第一个分隔符后，以角色的口吻和性格进行详细回复。**此回复必须是长篇幅的，包含对场景、动作、对话和心理活动的深入描写，确保正文字数不低于1000汉字。这是一个必须严格遵守的规则。**\n10. 在第二个分隔符后，用||-OPTION-SEPARATOR-||作为开始标记，然后换行，提供四个推演选项。\n11. **不要使用代码块**，严格按照下面的纯文本格式输出。\n\n[正式开始]\nnewTime: ${stateData.time}\nnewLocation: ${stateData.location}\nnewAge: ${stateData.age}\nnewRealm: ${stateData.realm}\nnewCharacterAttributes: 无\nnewItems: 无\nnewTasks: 无\ntaskProgress: 无\nrelationshipUpdates: 无\nnewRelationships: 无\nnewDiscoveredLocations: 无\n||-UI-SEPARATOR-||`;
                if (shouldRequestSummary) { prompt += `\n[附加指令]\n在第三个分隔符后，对本轮互动生成一个不超过50字的简短总结。\n||-SUMMARY-SEPARATOR-||`;}
                return prompt;
            };
            // (容错优化) 使用正则表达式增强解析的鲁棒性
            const parseAIResponse = (rawResponse, isOpeningScene = false) => {
                if (!rawResponse || typeof rawResponse !== 'string' || rawResponse.trim() === '') { return { parsedSuccessfully: false }; }

                // 使用更灵活的正则表达式来捕获各个数据块
                const separators = {
                    data: isOpeningScene ? /\|\|-OPENING-DATA-\|\|([\s\S]*?)\|\|-OPTION-SEPARATOR-\|\|/ : /\[正式开始\]\s*([\s\S]*?)\s*\|\|-UI-SEPARATOR-\|\|/,
                    narrative: isOpeningScene ? /^[\s\S]*?\|\|-OPENING-DATA-\|\|/ : /\|\|-UI-SEPARATOR-\|\|([\s\S]*?)(?:\|\|-OPTION-SEPARATOR-\|\||\|\|-SUMMARY-SEPARATOR-\|\||$)/,
                    options: /\|\|-OPTION-SEPARATOR-\|\|([\s\S]*?)(?:\|\|-SUMMARY-SEPARATOR-\|\||$)/,
                    summary: /\|\|-SUMMARY-SEPARATOR-\|\|([\s\S]*)$/
                };

                const dataMatch = rawResponse.match(separators.data);
                const narrativeMatch = rawResponse.match(separators.narrative);

                // 核心数据块和叙事块是必须的
                if (!dataMatch || !narrativeMatch) {
                    return { parsedSuccessfully: false, raw: rawResponse };
                }

                let narrativeText;
                if (isOpeningScene) {
                    narrativeText = rawResponse.substring(0, rawResponse.indexOf('||-OPENING-DATA-||')).trim();
                } else {
                    narrativeText = narrativeMatch[1] ? narrativeMatch[1].trim() : '';
                }

                // 即使叙事文本为空，也认为是格式错误，因为AI至少要回复
                if (!narrativeText && !isOpeningScene) return { parsedSuccessfully: false };

                const dataPart = dataMatch[1] ? dataMatch[1].trim() : '';

                // 可选部分
                const optionsMatch = rawResponse.match(separators.options);
                const summaryMatch = rawResponse.match(separators.summary);
                const options = optionsMatch && optionsMatch[1] ? optionsMatch[1].split('\n').map(o => o.trim()).filter(Boolean) : [];
                const summary = summaryMatch && summaryMatch[1] ? summaryMatch[1].trim() : null;

                // 开局场景需要特殊返回结构
                if (isOpeningScene) {
                    const optionsPart = optionsMatch ? optionsMatch[1].trim() : '';
                    return { parsedSuccessfully: true, openingText: narrativeText, dataPart: dataPart, optionsPart: optionsPart };
                }

                // 解析常规交互的数据
                const updatedState = {};
                let acquiredItems = [], newTasks = [], taskProgressUpdates = [], relationshipUpdates = [], newRelationships = [], newDiscoveredLocations = [], updatedAttributes = {};

                dataPart.split('\n').forEach(line => {
                    const separatorIndex = line.indexOf(':');
                    if (separatorIndex === -1) return;
                    const key = line.substring(0, separatorIndex).trim();
                    const value = line.substring(separatorIndex + 1).trim();

                    if (!key || !value || value.toLowerCase() === '无') return;
                    switch (key) {
                        case 'newTime': updatedState.time = value; break;
                        case 'newLocation': updatedState.location = value; break;
                        case 'newAge': updatedState.age = value; break;
                        case 'newRealm': updatedState.realm = value; break;
                        case 'newCharacterAttributes': updatedAttributes = safeJSONParse(value, {}); break;
                        case 'newItems': acquiredItems = value.split(';').map(itemStr => { const parts = itemStr.split('|'); return parts.length === 2 ? { name: parts[0].trim(), description: parts[1].trim() } : null; }).filter(Boolean); break;
                        case 'newTasks': newTasks = value.split(';').map(taskStr => { const match = taskStr.match(/\[(主线|支线)\](.*?)\|(.*?)\|(.*)/); if (!match) return null; return { type: match[1] === '主线' ? 'main' : 'side', title: match[2], description: match[3], reward: match[4] }; }).filter(Boolean); break;
                        case 'taskProgress': taskProgressUpdates = value.split(';').map(updateStr => { const [title, progress] = updateStr.split('|'); return { title: title.trim(), progress: parseInt(progress, 10) }; }).filter(u => u.title && !isNaN(u.progress)); break;
                        case 'relationshipUpdates': relationshipUpdates = value.split(';').map(updateStr => { const [name, change] = updateStr.split('|'); return { name: name.trim(), change: parseInt(change, 10) }; }).filter(u => u.name && !isNaN(u.change)); break;
                        case 'newRelationships': newRelationships = value.split(';').map(relStr => { const match = relStr.match(/\[(.*?)\](.*?)\|(.*?)\|(.*?)\|(.*?)\|(.*)/); if(!match) return null; return { identity: match[1], name: match[2], realm: match[3], description: match[4], relationType: match[5], favorability: parseInt(match[6], 10) }; }).filter(Boolean); break;
                        case 'newDiscoveredLocations': newDiscoveredLocations = value.split(';').map(locStr => { const parts = locStr.split('|'); return parts.length === 2 ? { name: parts[0].trim(), description: parts[1].trim() } : null; }).filter(Boolean); break;
                    }
                });
                return { responseText: narrativeText, parsedSuccessfully: true, updatedState, options, summary, acquiredItems, newTasks, taskProgressUpdates, relationshipUpdates, newRelationships, newDiscoveredLocations, updatedAttributes };
            };

            // 新增：格式化重试函数
            const formatAndRetryAIResponse = async (malformedResponse, isOpeningScene = false) => {
                let formatTemplate;
                if (isOpeningScene) {
                    formatTemplate = `[可选的叙事文本]\n||-OPENING-DATA-||\nage: ...\nrealm: ...\n...\n||-OPTION-SEPARATOR-||\n[选项1]\n...`;
                } else {
                    formatTemplate = `[正式开始]\nnewTime: ...\nnewLocation: ...\n...\n||-UI-SEPARATOR-||\n[叙事文本]\n||-OPTION-SEPARATOR-||\n[选项1]\n...\n||-SUMMARY-SEPARATOR-||\n[总结]`;
                }

                const retryPrompt = `[指令]：请严格按照以下格式模板，重新整理提供的混乱文本。不要添加任何解释，直接输出整理后的结果。\n\n[格式模板]\n${formatTemplate}\n\n[待整理的混乱文本]\n${malformedResponse}`;

                await triggerSlash(`/echo title="天机紊乱" 正在尝试重新梳理因果...`);
                return await triggerSlashWithResult(`/gen lock=on ${JSON.stringify(retryPrompt)}`);
            };


            // ---- 模块8: 游戏系统功能函数 ----
            const handleMajorSummary = async () => {
                if (isSummarizing) return;
                isSummarizing = true;
                await triggerSlash('/echo title="天机回溯" 正在凝练过往因果，生成前尘忆梦...');
                const summariesToProcess = smallSummaries.slice(0, 20);
                const majorSummaryPrompt = `根据以下20段剧情摘要，请将其融合成一个连贯、生动的段落，作为一段重要的剧情回忆：\n\n${summariesToProcess.join('\n')}\n\n请直接输出整合后的段落，不要添加任何额外的前缀或解释。`;
                try {
                    const majorSummary = await triggerSlashWithResult(`/gen lock=on ${JSON.stringify(majorSummaryPrompt)}`);
                    if (!majorSummary || majorSummary.trim() === '') throw new Error("AI未能生成有效的大总结内容。");
                    let lorebookName = await triggerSlashWithResult('/getcharbook type=primary');
                    if (!lorebookName || lorebookName.trim() === '') {
                        lorebookName = await triggerSlashWithResult('/getchatbook');
                        await triggerSlash('/echo title="提示" 当前角色卡未绑定主世界书，“前尘忆梦”已写入聊天世界书。建议为角色绑定专属世界书以获得最佳体验。');
                    }
                    if (lorebookName && lorebookName.trim() !== '') {
                        const existingEntries = await triggerSlashWithResult(`/findentry file="${lorebookName}" field=key "前尘忆梦"`);
                        const volume = existingEntries ? existingEntries.split(',').length + 1 : 1;
                        const key = `前尘忆梦 - 卷${volume}`;
                        const content = JSON.stringify(majorSummary);
                        const newEntryUID = await triggerSlashWithResult(`/createentry file="${lorebookName}" key="${key}" ${content}`);
                        if (newEntryUID) {
                            await triggerSlash(`/setentryfield file="${lorebookName}" uid=${newEntryUID} field=type constant`);
                            await triggerSlash(`/setentryfield file="${lorebookName}" uid=${newEntryUID} field=position after_character_definition`);
                            await triggerSlash(`/echo title="铭刻成功" 一卷新的记忆已被载入世界书《${lorebookName}》。`);
                            smallSummaries.splice(0, 20);
                        } else { throw new Error("创建世界书条目失败，未返回UID。"); }
                    } else { throw new Error("未能确定用于写入的世界书。"); }
                } catch (error) {
                    console.error("大总结生成或写入失败:", error);
                    await triggerSlash('/echo title="铭刻异常" 汇聚记忆时出现阻碍。');
                } finally { isSummarizing = false; }
            };
            const renderAttributePanel = () => {
                const panel = document.createElement('div');
                panel.className = 'attribute-panel';
                const attributes = worldState.characterAttributes;
                const categories = {
                    '根骨天赋': { minge: "命格", linggen: "灵根", tizhi_special: "体质", tianfu: "天赋" },
                    '功法神通': { gongfa: "功法", shentong: "神通" },
                    '法宝武器': { zhuangbei: "装备", wuqi: "武器", fabao: "法宝" },
                    '属性详览': { daoxin: "道心", qiyun: "气运", shenshi: "神识", fali: "法力", tizhi_attr: "体魄", meili: "魅力" }
                };

                for (const categoryName in categories) {
                    const categoryDiv = document.createElement('div');
                    categoryDiv.className = 'attribute-category';
                    const title = document.createElement('h3');
                    title.textContent = categoryName;
                    categoryDiv.appendChild(title);

                    const list = document.createElement('ul');
                    list.className = 'attribute-list';

                    const keys = categories[categoryName];
                    for(const key in keys) {
                        if(Object.prototype.hasOwnProperty.call(attributes, key)) {
                            const item = document.createElement('li');
                            item.className = 'attribute-item';

                            const nameSpan = document.createElement('span');
                            nameSpan.className = 'attribute-name';
                            nameSpan.textContent = keys[key];

                            const valueSpan = document.createElement('span');
                            valueSpan.className = 'attribute-value';
                            valueSpan.textContent = attributes[key];

                            item.append(nameSpan, valueSpan);
                            list.appendChild(item);
                        }
                    }
                    categoryDiv.appendChild(list);
                    panel.appendChild(categoryDiv);
                }
                return panel;
            };
            const showItemActionMenu = (itemId) => {
                const item = worldState.inventory.find(i => i.id === itemId); if (!item) return;
                const container = document.createElement('div'); container.className = 'item-action-container animate-fade-in-up';
                container.innerHTML = `<h2>${item.name}${item.quantity > 1 ? ` (x${item.quantity})` : ''}</h2><p>${item.description}</p>`;
                const actionGroup = document.createElement('div'); actionGroup.className = 'options-group'; actionGroup.style.flexDirection = 'row';
                const useBtn = document.createElement('button'); useBtn.className = 'menu-option-btn'; useBtn.textContent = '使用'; useBtn.onclick = () => handleItemUse(itemId);
                const discardBtn = document.createElement('button'); discardBtn.className = 'menu-option-btn'; discardBtn.style.background = 'linear-gradient(to bottom, #a94442, #8B0000)'; discardBtn.textContent = '丢弃'; discardBtn.onclick = () => handleItemDiscard(itemId);
                actionGroup.append(useBtn, discardBtn); container.appendChild(actionGroup);
                const backBtn = document.createElement('button'); backBtn.className = 'menu-option-btn'; backBtn.textContent = '返回'; backBtn.style.marginTop = '20px'; backBtn.onclick = () => showMenuInMainPanel(activeMenuButton); container.appendChild(backBtn);
                textScroll.innerHTML = ''; textScroll.appendChild(container);
            };
            const handleItemUse = async (itemId) => {
                const itemIndex = worldState.inventory.findIndex(i => i.id === itemId); if (itemIndex === -1) return;
                const item = worldState.inventory[itemIndex]; userInput.value = `你使用了“${item.name}”。`;
                if (item.quantity > 1) { worldState.inventory[itemIndex].quantity--; } else { worldState.inventory.splice(itemIndex, 1); }
                await hideMenuAndReturn(); await handleInteraction();
            };
            const handleItemDiscard = async (itemId) => {
                const itemIndex = worldState.inventory.findIndex(i => i.id === itemId); if (itemIndex === -1) return;
                const item = worldState.inventory[itemIndex];
                if (confirm(`是否确定要丢弃“${item.name}”？此操作无法撤销。`)) {
                    if (item.quantity > 1) { worldState.inventory[itemIndex].quantity--; } else { worldState.inventory.splice(itemIndex, 1); }
                    await triggerSlash(`/echo title="袖里乾坤" 已丢弃物品：${item.name}`); await saveStateToSillyTavern(); showMenuInMainPanel(activeMenuButton);
                }
            };
            const handleRelationshipSever = async (characterId) => {
                const characterIndex = worldState.relationships.findIndex(r => r.id === characterId); if (characterIndex === -1) return;
                const characterName = worldState.relationships[characterIndex].name;
                if (confirm(`是否确定要斩断与【${characterName}】的全部因果？此行径逆天而行，将无法挽回。`)) {
                    worldState.relationships.splice(characterIndex, 1);
                    await saveStateToSillyTavern();
                    await triggerSlash(`/echo title="因果已断" 你与【${characterName}】的尘缘已化为飞灰。`);
                    showMenuInMainPanel(activeMenuButton);
                }
            };
            const renderTaskItem = (task) => {
                const itemDiv = document.createElement('div');
                itemDiv.className = 'task-item';
                if(task.status === 'completed') itemDiv.classList.add('task-completed');
                const progressBarHTML = task.status === 'active' ? `<div class="progress-bar-container"><div class="progress-bar" style="width: ${task.progress}%;"></div><span class="progress-text">${task.progress}%</span></div>` : '';
                const rewardHTML = `<div class="task-reward"><b>奖励：</b>${task.reward}</div>`;
                itemDiv.innerHTML = `<div class="task-header"><span class="task-title">${task.title}</span><span class="task-type ${task.type}">${task.type === 'main' ? '主线' : '支线'}</span></div><p class="task-description">${task.description}</p>${progressBarHTML}${rewardHTML}`;
                return itemDiv;
            };
            const renderRelationshipCard = (rel) => {
                const cardDiv = document.createElement('div');
                cardDiv.className = 'relationship-card';
                const favorPercent = rel.favorability;
                const barColor = `linear-gradient(to right, #c0392b 0%, #e67e22 ${Math.min(25, favorPercent) * 2}%, #f1c40f ${Math.min(50, favorPercent) * 2}%, #2ecc71 ${favorPercent * 2}%)`;
                cardDiv.innerHTML = `<div class="relationship-header"><span class="relationship-name">${rel.name}</span><span class="relationship-meta">${rel.identity} | ${rel.realm}</span></div><p class="relationship-desc">${rel.description}</p><div class="favor-label"><span>关系：${rel.relationType}</span><span class="favor-value">好感：${favorPercent}/100</span></div><div class="favor-bar-container"><div class="favor-bar" style="width: ${favorPercent}%; background: ${barColor};"></div><span class="progress-text">${favorPercent}%</span></div><div class="relationship-actions"><button class="sever-relationship-btn" data-id="${rel.id}">斩断因果</button></div>`;
                return cardDiv;
            };

            // ---- 模块9: 核心交互循环 ----
            const handleInteraction = async () => {
                if ((currentMode !== 'INTERACTION_MODE' && modeBeforeMenu !== 'INTERACTION_MODE') || sendButton.disabled) return;
                let userMessage = userInput.value.trim();

                if (!userMessage) {
                    if (isAwaitingFirstAction) {
                        await triggerSlash(`/echo title="天机重演" 正在重新衍化开局因果...`);
                        await generateOpeningScene(worldState.sex);
                        return;
                    }
                    if (lastUserMessage && lastInteractionSnapshot.worldState) {
                        userMessage = lastUserMessage;
                        worldState = JSON.parse(JSON.stringify(lastInteractionSnapshot.worldState));
                        chatDisplayContent = lastInteractionSnapshot.chatDisplayContent;
                        smallSummaries = [...lastInteractionSnapshot.smallSummaries];
                        deductionOptions = [...lastInteractionSnapshot.deductionOptions];
                        renderContent();
                        await triggerSlash(`/echo title="天机重演" 正在重新衍化因果...`);
                    } else { return; }
                } else {
                    lastUserMessage = userMessage;
                    isAwaitingFirstAction = false;
                }

                lastInteractionSnapshot = {
                    worldState: JSON.parse(JSON.stringify(worldState)),
                    chatDisplayContent: chatDisplayContent,
                    smallSummaries: [...smallSummaries],
                    deductionOptions: [...deductionOptions]
                };

                if (typeof triggerSlashWithResult !== 'function') {
                    const errorHTML = '<p style="color:red;"><b>错误:</b> 无法连接到SillyTavern核心功能。</p>';
                    appendMessage(errorHTML);
                    return;
                }

                const userMessageHTML = `<div class="user-message">你: ${userMessage}</div>`;
                chatDisplayContent += userMessageHTML;
                appendMessage(userMessageHTML);

                userInput.value = ''; sendButton.disabled = true; sendButton.textContent = '推演中';

                const thinkingHTML = `<p class="thinking-indicator" style="margin-top:10px; text-align: center; color: #8D6E63; font-style: italic;">天机衍化中，云海翻腾...</p>`;
                appendMessage(thinkingHTML);

                const shouldRequestSummary = true;
                const prompt = buildPromptForAI(userMessage, shouldRequestSummary);
                const command = `/gen lock=on ${JSON.stringify(prompt)}`;
                try {
                    let rawResponse = await triggerSlashWithResult(command);
                    let { parsedSuccessfully, ...parsedResult } = parseAIResponse(rawResponse);

                    // (容错逻辑) 如果初次解析失败，则进行格式化重试
                    if (!parsedSuccessfully) {
                        const reformattedResponse = await formatAndRetryAIResponse(rawResponse);
                        const secondParse = parseAIResponse(reformattedResponse);
                        if (!secondParse.parsedSuccessfully) throw new Error("AI未能正确遵循格式，即使在重试后。");
                        parsedResult = secondParse;
                    }

