<body>
    <!-- 主容器 -->
    <div class="fused-scroll-container">
        <!-- 背景动态粒子效果 -->
        <div class="spiritual-energy-flow"></div>

        <!-- 主要内容区 -->
        <div class="fused-scroll-content">
            <!-- 左侧面板 -->
            <div class="left-panel">
                <!-- 角色头像与信息区 -->
                <div class="avatar-section">
                    <div class="embedded-avatar"><div class="user_avatar"></div></div>
                    <div class="avatar-info-panel">
                        <div class="info-item"><strong class="info-name">{{user}}</strong></div>
                        <div class="info-item"><strong>性别:</strong> <span id="charSex">未知</span></div>
                        <div class="info-item"><strong>年龄:</strong> <span id="charAge">未知</span></div>
                        <div class="info-item"><strong>境界:</strong> <span id="charRealm">未知</span></div>
                    </div>
                </div>
                <!-- 功能导航按钮区 -->
                <div class="function-nav-area">
                    <div class="function-nav-button" data-menu="灵境感知" data-trigram="☰"><span>灵境感知</span></div>
                    <div class="function-nav-button" data-menu="周天舆图" data-trigram="☷"><span>周天舆图</span></div>
                    <div class="function-nav-button" data-menu="尘缘绘卷" data-trigram="☲"><span>尘缘绘卷</span></div>
                    <div class="function-nav-button" data-menu="诸天宝录" data-trigram="☳"><span>诸天宝录</span></div>
                    <div class="function-nav-button" data-menu="袖里乾坤" data-trigram="☶"><span>袖里乾坤</span></div>
                    <div class="function-nav-button" data-menu="前尘忆梦" data-trigram="☵"><span>前尘忆梦</span></div>
                    <div class="function-nav-button" data-menu="天机推演" data-trigram="☴"><span>天机推演</span></div>
                    <div class="function-nav-button" data-menu="轮回之刻" data-trigram="☱"><span>轮回之刻</span></div>
                </div>
            </div>
            <!-- 右侧面板 -->
            <div class="right-panel">
                <!-- 顶部标题 -->
                <div class="fused-scroll-header"><div class="header-title-text">太虚幻境</div></div>
                <!-- 日历与地点信息 -->
                <div class="calendar-bar"><div><span class="time-info">未知</span><br><span class="location-info">未知</span></div></div>
                <!-- 主要文本显示区 -->
                <div class="text-scroll-area">
                    <div class="lined-paper-overlay"></div>
                    <div class="text-scroll"></div>
                </div>
                <!-- 用户输入区 -->
                <div class="message-input-area">
                    <textarea id="userInput" placeholder="传音入密，衍化天机..."></textarea>
                    <button id="sendButton">传音</button>
                </div>
            </div>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', async () => {
            // ---- 模块1: DOM元素获取与缓存 ----
            // 缓存所有需要频繁操作的DOM元素，提高性能
            const sendButton = document.getElementById('sendButton');
            const userInput = document.getElementById('userInput');
            const textScroll = document.querySelector('.text-scroll');
            const timeInfoElem = document.querySelector('.time-info');
            const locationInfoElem = document.querySelector('.location-info');
            const charSexElem = document.getElementById('charSex');
            const charAgeElem = document.getElementById('charAge');
            const charRealmElem = document.getElementById('charRealm');
            const functionNavArea = document.querySelector('.function-nav-area');

            // ---- 模块2: 全局状态与核心数据 ----
            // 默认的世界状态，作为新游戏或加载失败时的基础
            const defaultWorldState = {
                sex: "未知", age: "未知", realm: "未知", time: "未知", location: "未知",
                inventory: [], tasks: [], relationships: [], discoveredLocations: [],
                characterAttributes: {
                    minge: "待定", linggen: "待定", tizhi_special: "待定",
                    tianfu: "待定", gongfa: "无", shentong: "无",
                    zhuangbei: "无", wuqi: "无", fabao: "无", daoxin: 0, qiyun: 0, shenshi: 0,
                    fali: 0, tizhi_attr: 0, meili: 0
                }
            };
            const MAX_SAVE_SLOTS = 8;
            // 核心状态变量
            let currentMode = 'GUIDE_MODE'; // 控制当前UI显示模式
            let worldState = { ...defaultWorldState }; // 存储所有游戏世界的数据
            let chatDisplayContent = ""; // 缓存聊天内容的HTML字符串，用于完整重绘
            let deductionOptions = []; // AI提供的推演选项
            let smallSummaries = []; // 中期记忆摘要列表
            let interactionCounter = 0; // 交互计数器（暂未完全利用）
            let isSummarizing = false; // 大总结任务进行中的标志位，防止重复触发
            let activeMenuButton = null; // 当前激活的导航按钮
            let modeBeforeMenu = null; // 进入菜单前的UI模式，用于返回
            let currentCharacterName = 'default_char'; // 当前聊天标识符，用于存档
            let lastUserMessage = ""; // 缓存上一次用户输入，用于重试
            let isAwaitingFirstAction = false; // 是否等待开局后的第一次行动
            let lastInteractionSnapshot = {}; // 用于“天机重演”功能的交互快照
            let lastSavedWorldState = null; // 用于增量保存的状态快照

            // ---- 模块3: 核心辅助函数 ----
            // Base64编码/解码，用于在SillyTavern变量中安全存储复杂数据
            const encodeText = (text) => btoa(unescape(encodeURIComponent(text)));
            const decodeText = (b64) => decodeURIComponent(escape(atob(b64)));
            // 安全的JSON解析函数，增加对常见错误的修复能力
            const safeJSONParse = (jsonString, defaultValue) => {
                if (!jsonString || typeof jsonString !== 'string' || jsonString.trim() === '' || jsonString === 'undefined' || jsonString === 'null') return defaultValue;
                try {
                    // 尝试修复JSON中常见的末尾逗号错误
                    const fixedJsonString = jsonString.replace(/,\s*([}\]])/g, '$1');
                    return JSON.parse(fixedJsonString);
                } catch (e) {
                    console.error("JSON 解析失败:", e, "原始字符串:", jsonString);
                    return defaultValue;
                }
            };
            // 从SillyTavern获取当前聊天文件名作为角色标识
            const getCurrentCharacterNameFromTavern = async () => {
                if (typeof triggerSlashWithResult !== 'function') return 'default_character';
                try {
                    const name = await triggerSlashWithResult('/getchatname');
                    return (name && name.trim() !== '' && name !== 'undefined') ? name.replace('.jsonl', '') : 'default_character';
                } catch (e) { return 'default_character'; }
            };
            // 深层比较两个对象是否相等，用于增量保存的判断
            const deepEqual = (obj1, obj2) => {
                if (obj1 === obj2) return true;
                if (typeof obj1 !== 'object' || obj1 === null || typeof obj2 !== 'object' || obj2 === null) return false;
                const keys1 = Object.keys(obj1);
                const keys2 = Object.keys(obj2);
                if (keys1.length !== keys2.length) return false;
                for (let key of keys1) {
                    if (!keys2.includes(key) || !deepEqual(obj1[key], obj2[key])) return false;
                }
                return true;
            };

            // ---- 模块4: 状态持久化（存档/读档）----
            // 将游戏状态保存到SillyTavern全局变量中（已实现增量检查）
            const saveStateToSillyTavern = async () => {
                if (typeof triggerSlash !== 'function' || !currentCharacterName) return;
                // 只有在世界状态发生真实变化时才执行保存，避免不必要的性能开销
                if (lastSavedWorldState && deepEqual(worldState, lastSavedWorldState)) {
                    return;
                }
                const characterState = {
                    currentUIMode: currentMode, worldGlobalState: worldState, chatDisplayContent: chatDisplayContent,
                    deductionOptions: deductionOptions, smallSummaries: smallSummaries, interactionCounter: interactionCounter,
                    lastUserMessage: lastUserMessage, isAwaitingFirstAction: isAwaitingFirstAction, TavernSaveSlots: await getSaveSlots()
                };
                const stateJson = JSON.stringify(characterState);
                await triggerSlash(`/setglobalvar key=persistentUIStates index="${currentCharacterName}" ${stateJson}`);
                // 更新上一次成功保存的状态快照
                lastSavedWorldState = JSON.parse(JSON.stringify(worldState));
            };
            // 从SillyTavern全局变量中加载游戏状态
            const loadStateFromSillyTavern = async () => {
                if (typeof triggerSlashWithResult !== 'function') return false;
                currentCharacterName = await getCurrentCharacterNameFromTavern();
                // 优先处理通过URL参数传递的临时读档数据
                const loadMode = await triggerSlashWithResult('/getvar key=st_ui_load_mode');
                if (loadMode && loadMode.trim() !== '') {
                    try {
                        const b64_worldState = await triggerSlashWithResult('/getvar key=st_ui_load_world');
                        const b64_chatContent = await triggerSlashWithResult('/getvar key=st_ui_load_chat');
                        const b64_deductionOptions = await triggerSlashWithResult('/getvar key=st_ui_load_options');
                        const b64_smallSummaries = await triggerSlashWithResult('/getvar key=st_ui_load_summaries');
                        const savedCounter = await triggerSlashWithResult('/getvar key=st_ui_load_counter');
                        const savedLastMessage = await triggerSlashWithResult('/getvar key=st_ui_load_last_message');
                        currentMode = loadMode;
                        worldState = JSON.parse(decodeText(b64_worldState));
                        chatDisplayContent = decodeText(b64_chatContent);
                        deductionOptions = JSON.parse(decodeText(b64_deductionOptions || '[]'));
