                const itemDiv = document.createElement('div');
                itemDiv.className = 'task-item';
                if(task.status === 'completed') itemDiv.classList.add('task-completed');
                const progressBarHTML = task.status === 'active' ? `<div class="progress-bar-container"><div class="progress-bar" style="width: ${task.progress}%;"></div><span class="progress-text">${task.progress}%</span></div>` : '';
                const rewardHTML = `<div class="task-reward"><b>奖励：</b>${task.reward}</div>`;
                itemDiv.innerHTML = `<div class="task-header"><span class="task-title">${task.title}</span><span class="task-type ${task.type}">${task.type === 'main' ? '主线' : '支线'}</span></div><p class="task-description">${task.description}</p>${progressBarHTML}${rewardHTML}`;
                return itemDiv;
            };
            const renderRelationshipCard = (rel) => {
                const cardDiv = document.createElement('div');
                cardDiv.className = 'relationship-card';
                const favorPercent = rel.favorability;
                const barColor = `linear-gradient(to right, #c0392b 0%, #e67e22 ${Math.min(25, favorPercent) * 2}%, #f1c40f ${Math.min(50, favorPercent) * 2}%, #2ecc71 ${favorPercent * 2}%)`;
                cardDiv.innerHTML = `<div class="relationship-header"><span class="relationship-name">${rel.name}</span><span class="relationship-meta">${rel.identity} | ${rel.realm}</span></div><p class="relationship-desc">${rel.description}</p><div class="favor-label"><span>关系：${rel.relationType}</span><span class="favor-value">好感：${favorPercent}/100</span></div><div class="favor-bar-container"><div class="favor-bar" style="width: ${favorPercent}%; background: ${barColor};"></div><span class="progress-text">${favorPercent}%</span></div><div class="relationship-actions"><button class="sever-relationship-btn" data-id="${rel.id}">斩断因果</button></div>`;
                return cardDiv;
            };

            // ---- 模块9: 核心交互循环 ----
            const handleInteraction = async () => {
                if ((currentMode !== 'INTERACTION_MODE' && modeBeforeMenu !== 'INTERACTION_MODE') || sendButton.disabled) return;
                let userMessage = userInput.value.trim();

                if (!userMessage) {
                    if (isAwaitingFirstAction) {
                        await triggerSlash(`/echo title="天机重演" 正在重新衍化开局因果...`);
                        await generateOpeningScene(worldState.sex);
                        return;
                    }
                    if (lastUserMessage && lastInteractionSnapshot.worldState) {
                        userMessage = lastUserMessage;
                        worldState = JSON.parse(JSON.stringify(lastInteractionSnapshot.worldState));
                        chatDisplayContent = lastInteractionSnapshot.chatDisplayContent;
                        smallSummaries = [...lastInteractionSnapshot.smallSummaries];
                        deductionOptions = [...lastInteractionSnapshot.deductionOptions];
                        renderContent();
                        await triggerSlash(`/echo title="天机重演" 正在重新衍化因果...`);
                    } else { return; }
                } else {
                    lastUserMessage = userMessage;
                    isAwaitingFirstAction = false;
                }

                lastInteractionSnapshot = {
                    worldState: JSON.parse(JSON.stringify(worldState)),
                    chatDisplayContent: chatDisplayContent,
                    smallSummaries: [...smallSummaries],
                    deductionOptions: [...deductionOptions]
                };

                if (typeof triggerSlashWithResult !== 'function') {
                    const errorHTML = '<p style="color:red;"><b>错误:</b> 无法连接到SillyTavern核心功能。</p>';
                    appendMessage(errorHTML);
                    return;
                }

                const userMessageHTML = `<div class="user-message">你: ${userMessage}</div>`;
                chatDisplayContent += userMessageHTML;
                appendMessage(userMessageHTML);

                userInput.value = ''; sendButton.disabled = true; sendButton.textContent = '推演中';

                const thinkingHTML = `<p class="thinking-indicator" style="margin-top:10px; text-align: center; color: #8D6E63; font-style: italic;">天机衍化中，云海翻腾...</p>`;
                appendMessage(thinkingHTML);

                const shouldRequestSummary = true;
                const prompt = buildPromptForAI(userMessage, shouldRequestSummary);
                const command = `/gen lock=on ${JSON.stringify(prompt)}`;
                try {
                    let rawResponse = await triggerSlashWithResult(command);
                    let { parsedSuccessfully, ...parsedResult } = parseAIResponse(rawResponse);

                    // (容错逻辑) 如果初次解析失败，则进行格式化重试
                    if (!parsedSuccessfully) {
                        const reformattedResponse = await formatAndRetryAIResponse(rawResponse);
                        const secondParse = parseAIResponse(reformattedResponse);
                        if (!secondParse.parsedSuccessfully) throw new Error("AI未能正确遵循格式，即使在重试后。");
                        parsedResult = secondParse;
                    }

                    const { responseText, updatedState, options, summary, acquiredItems, newTasks, taskProgressUpdates, relationshipUpdates, newRelationships, newDiscoveredLocations, updatedAttributes } = parsedResult;

                    document.querySelector('.thinking-indicator')?.remove();

                    // 确保解析成功才继续处理
                    worldState = { ...worldState, ...updatedState };
                    if (updatedAttributes) { worldState.characterAttributes = { ...worldState.characterAttributes, ...updatedAttributes }; }
                    updateInventory(acquiredItems);
                    newDiscoveredLocations.forEach(locData => {
                        if (!worldState.discoveredLocations.some(loc => loc.name === locData.name)) {
                            worldState.discoveredLocations.push({ name: locData.name, description: locData.description });
                            triggerSlash(`/echo title="舆图更新" 你发现了新的区域：${locData.name}`);
                        }
                    });
                    relationshipUpdates.forEach(update => { const rel = worldState.relationships.find(r => r.name === update.name); if(rel) { rel.favorability = Math.min(100, Math.max(0, rel.favorability + update.change)); triggerSlash(`/echo title="尘缘变动" 你与${rel.name}的好感度变化了${update.change > 0 ? `+${update.change}` : update.change}。`); } });
                    newRelationships.forEach(relData => { if(!worldState.relationships.find(r => r.name === relData.name)) { worldState.relationships.push({ id: `rel_${Date.now()}_${Math.random()}`, ...relData }); triggerSlash(`/echo title="新的因果" 你结识了新的角色：${relData.name}。`); } });
                    newTasks.forEach(taskData => { if (!worldState.tasks.find(t => t.title === taskData.title)) { worldState.tasks.push({ id: `task_${Date.now()}_${Math.random()}`, ...taskData, status: 'active', progress: 0 }); triggerSlash(`/echo title="天命更新" 新的任务已添加至诸天宝录：${taskData.title}`); } });
                    taskProgressUpdates.forEach(update => { const task = worldState.tasks.find(t => t.title === update.title && t.status === 'active'); if (task) { task.progress = Math.max(task.progress, update.progress); if (task.progress >= 100) { task.status = 'completed'; triggerSlash(`/echo title="天命已了" 任务完成：${task.title}！获得奖励：${task.reward}`); } } });

                    const aiMessageHTML = `<div class="ai-message">${responseText.replace(/\n/g, '<br>')}</div>`;
                    chatDisplayContent += aiMessageHTML;
                    appendMessage(aiMessageHTML);

                    deductionOptions = options || [];
                    if (summary) { smallSummaries.push(summary); }

                    if (summary && smallSummaries.length >= 20) { await handleMajorSummary(); }

                    updateCalendarBar();
                    updateAvatarPanel();

                } catch (error) {
                    console.error("AI交互错误:", error);
                    document.querySelector('.thinking-indicator')?.remove();
                    const errorHTML = `<p style="color:red; margin-top:10px;"><b>错误:</b> ${error.message}</p>`;
                    appendMessage(errorHTML);
                } finally {
                    await saveStateToSillyTavern();
                    sendButton.disabled = false;
                    sendButton.textContent = '传音';
                }
            };
            sendButton.addEventListener('click', handleInteraction);
            userInput.addEventListener('keydown', (event) => { if (event.key === 'Enter' && !event.shiftKey) { event.preventDefault(); handleInteraction(); } });

            // ---- 模块10: 视觉效果与启动 ----
            const createRipple = (event) => { const target = event.currentTarget; const circle = document.createElement("span"); const diameter = Math.max(target.clientWidth, target.clientHeight); const radius = diameter / 2; Object.assign(circle.style, { width: `${diameter}px`, height: `${diameter}px`, left: `${event.clientX - target.getBoundingClientRect().left - radius}px`, top: `${event.clientY - target.getBoundingClientRect().top - radius}px`, }); circle.classList.add("ripple"); target.querySelector(".ripple")?.remove(); target.appendChild(circle); };
            const initSpiritualParticles = () => { const particleContainer = document.querySelector('.spiritual-energy-flow'); for (let i = 0; i < 15; i++) { const particle = document.createElement('div'); particle.classList.add('energy-particle-item'); const size = Math.random() * 3 + 1; Object.assign(particle.style, { width: `${size}px`, height: `${size}px`, left: `${Math.random() * 100}%`, top: `${Math.random() * 100}%`, animationDuration: `${Math.random() * 15 + 20}s`, animationDelay: `-${Math.random() * 20}s`, }); particle.style.setProperty('--x-end', `${(Math.random() - 0.5) * 400}px`); particle.style.setProperty('--y-end', `${(Math.random() - 0.5) * 400}px`); particle.style.setProperty('--scale-end', `${Math.random() * 0.2}`); particleContainer.appendChild(particle); } };
            document.body.addEventListener('click', (event) => { const interactableArea = event.target.closest('.guide-btn, .creation-btn, .function-nav-button, .menu-option-btn, .deduction-option-btn, .message-input-area button, .delete-save-btn, .sever-relationship-btn, .map-location-btn'); if (interactableArea) createRipple({ currentTarget: interactableArea, clientX: event.clientX, clientY: event.clientY }); });
            initSpiritualParticles();
            initializeUI();
        });
    </script>
</body>
